export interface Product {
  id: string;
  name: string;
  description: string | null;
  /** Price as received from the API (Decimal serialized as number). */
  price: number;
  stock_quantity: number;
  category: string;
  /** Raw S3 object key (e.g. "products/<uuid>/<uuid>.webp").  For display, use image_download_url. */
  image_url: string | null;
  /** Presigned S3 download URL generated by the backend — use this in <img> tags. */
  image_download_url: string | null;
  created_at: string;
  updated_at: string;
}

export interface ProductListResponse {
  items: Product[];
  total: number;
  page: number;
  page_size: number;
  total_pages: number;
}

export interface ProductCreate {
  name: string;
  description?: string | null;
  price: number;
  stock_quantity?: number;
  category: string;
  image_url?: string | null;
}

export interface ProductUpdate {
  name?: string;
  description?: string | null;
  price?: number;
  stock_quantity?: number;
  category?: string;
  image_url?: string | null;
}

